  name: 'Ваша Компания',
  service: 'ваша услуга/продукт',
  benefits: 'ключевые преимущества',
  contactPerson: 'Ваше Имя',
  position: 'Ваша Должность',
  phone: '+7 (999) 123-45-67',
  email: 'your@email.ru',
  website: 'https://your-company.ru'
};

const templateData = {
  // Данные получателя
  recipient_company: item['Company Name'] || 'Компания',
  recipient_contact: item['Contact Person'] || 'Уважаемый(ая) коллега',
  recipient_email: item['Email'],
  recipient_phone: item['Phone'],
  recipient_address: item['Address'],
