  sender_service: yourCompanyInfo.service,
  sender_benefits: yourCompanyInfo.benefits,
  sender_contact: yourCompanyInfo.contactPerson,
  sender_position: yourCompanyInfo.position,
  sender_phone: yourCompanyInfo.phone,
  sender_email: yourCompanyInfo.email,
  sender_website: yourCompanyInfo.website,

  // Мета-данные
  site_id: item['Site ID'],
  generated_at: new Date().toISOString()
};

return { json: templateData };

