parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const response = item.json;
    const metadata = $('📝 Подготовить данные для шаблона').item.json;

    // Проверка на ошибку API
    if (response.error) {
      console.error('Perplexity API Error:', response.error);
      results.push({
        json: {
          site_id: metadata.site_id,
          company_name: metadata.recipient_company,
          email: metadata.recipient_email,
          subject: `Коммерческое предложение от ${metadata.sender_company}`,
          body: `<p>Уважаемый(ая) ${metadata.recipient_contact}!</p><p>Мы заинтересованы в сотрудничестве с вашей компанией ${metadata.recipient_company}.</p><p>С уважением,<br>${metadata.sender_contact}<br>${metadata.sender_position}<br>${metadata.sender_company}</p>`,
          error: response.error.message,
          generated_at: metadata.generated_at
        }
      });
      continue;
    }

    // Извлекаем текст ответа от AI
    let aiContent = response.choices?.[0]?.message?.content || '{}';

    // Очищаем от markdown блоков если есть
    aiContent = aiContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // Парсим JSON
    let proposalData = {};
    try {
      proposalData = JSON.parse(aiContent);
    } catch (parseError) {
      console.error('JSON parse error:', parseError.message);
      console.log('AI Content:', aiContent);
      // Если не удалось распарсить - используем fallback
      proposalData = {
        subject: `Коммерческое предложение от ${metadata.sender_company}`,
        body: `<p>Уважаемый(ая) ${metadata.recipient_contact}!</p><p>Предлагаем рассмотреть возможность сотрудничества.</p><p>С уважением,<br>${metadata.sender_contact}<br>${metadata.sender_position}<br>${metadata.sender_company}</p>`
      };
    }

    results.push({
      json: {
        site_id: metadata.site_id,
        company_name: metadata.recipient_company,
        email: metadata.recipient_email,
        subject: proposalData.subject || 'Коммерческое предложение',
        body: proposalData.body || '',
        generated_at: metadata.generated_at,
        raw_ai_response: aiContent
      }
    });

  } catch (error) {
    console.error(`Error processing AI response: ${error.message}`);
  }
}

return results;
